package com.vandorlabs.neoforge.copifier;

import com.vandorlabs.light.ProgrammableLightPolicy;
import com.vandorlabs.neoforge.*;
import com.vandorlabs.neoforge.light.*;
import com.vandorlabs.neoforge.screen.*;
import com.vandorlabs.persistence.*;
import com.vandorlabs.redstone.*;
import com.vandorlabs.tiles.*;
import net.minecraft.nbt.*;

/** Bounded scalar Light clipboard plan; no inventory, host or world is retained. */
public final class NativeCopifierLightEdit {
    public record Plan(boolean applicable,CompoundTag fields) {
        public Plan {fields=fields.copy();}
        @Override public CompoundTag fields(){return fields.copy();}
    }
    private static int integer(CompoundTag tag,String key,int fallback){return tag.contains(key,Tag.TAG_INT)?tag.getInt(key):fallback;}
    private static boolean flag(CompoundTag tag,String key,boolean fallback){return tag.contains(key,Tag.TAG_BYTE)?tag.getBoolean(key):fallback;}
    private static CompoundTag normalize(CompoundTag current){
        var normalized=NativeScreenArtworkMigration.normalize(current,NativeScreenCatalog.INSTANCE);var inherited=NativeScreenSettings.read(normalized,NativeScreenCatalog.INSTANCE);var out=new CompoundTag();inherited.write(out);NativeLightSettings.read(normalized,inherited.channels(),NativeScreenCatalog.INSTANCE::material).write(out);FrameSettings.read(new ModernHousingTags(normalized),NativeScreenCatalog.INSTANCE::validFrame,NativeScreenCatalog.INSTANCE::validFrameSurface,NativeScreenCatalog.INSTANCE::validMaterial).write(new ModernHousingTags(out));
        var saved=normalized.getCompound("ForgeData").getCompound(TransmissionSettings.SETTINGS).getCompound("main");if(!saved.isEmpty()){var main=new CompoundTag();main.putIntArray("Channels",TransmissionSettings.readChannels(saved.contains("Channels",Tag.TAG_INT_ARRAY),saved.getIntArray("Channels"),ChannelList.EMPTY).toArray());main.putInt("Range",TransmissionSettings.readRange(saved.contains("Range",Tag.TAG_INT),saved.getInt("Range"),true));main.putBoolean("Local",TransmissionSettings.readLocal(saved.contains("Local",Tag.TAG_BYTE),saved.getBoolean("Local"),false));var all=new CompoundTag();all.put("main",main);var forge=new CompoundTag();forge.put(TransmissionSettings.SETTINGS,all);out.put("ForgeData",forge);}return out;
    }
    public static CompoundTag capture(NativeLightBlock.Kind kind,CompoundTag current){
        var fields=normalize(current);var inherited=NativeScreenSettings.read(fields,NativeScreenCatalog.INSTANCE);var light=NativeLightSettings.read(fields,inherited.channels(),NativeScreenCatalog.INSTANCE::material).light();var out=new CompoundTag();out.putInt("wall_texture",inherited.housing().mainTexture);out.putString("primary_kind","light");out.putInt("primary_texture",light.texture);out.putInt("light_face_texture",light.faceTexture<0?HousingFinishCatalog.legacyCount()+ProgrammableLightTextures.clamp(light.texture):light.faceTexture);out.putInt("light_off_face_texture",light.offFaceTexture);out.putInt("light_level",light.configuredLevel);var signal=new CompoundTag();signal.putBoolean("Brightness",light.signalBrightness);signal.putInt("Offset",light.offset);out.put("signal_settings",signal);out.putBoolean("small_input",kind==NativeLightBlock.Kind.FRAME&&inherited.scalar().smallInput);out.putBoolean("slab_tile_sides",inherited.housing().tileSides);out.putInt("texture_layout",inherited.housing().layout());out.putInt("redstone_trigger",light.trigger);out.putBoolean("join",light.join);out.putBoolean("active",light.manualOn);var channels=inherited.channels();if(channels.size()<=1)out.putInt("redstone_channel",channels.first());else out.putIntArray("redstone_channel",channels.toArray());var frames=new CompoundTag();FrameSettings.read(new ModernHousingTags(fields),NativeScreenCatalog.INSTANCE::validFrame,NativeScreenCatalog.INSTANCE::validFrameSurface,NativeScreenCatalog.INSTANCE::validMaterial).write(new ModernHousingTags(frames));out.put("FrameAppearance",frames);var saved=fields.getCompound("ForgeData").getCompound(TransmissionSettings.SETTINGS).getCompound("main");var transmission=new CompoundTag();transmission.putIntArray("Channels",TransmissionSettings.readChannels(saved.contains("Channels",Tag.TAG_INT_ARRAY),saved.getIntArray("Channels"),ChannelList.EMPTY).toArray());transmission.putInt("Range",TransmissionSettings.readRange(saved.contains("Range",Tag.TAG_INT),saved.getInt("Range"),true));transmission.putBoolean("Local",TransmissionSettings.readLocal(saved.contains("Local",Tag.TAG_BYTE),saved.getBoolean("Local"),false));out.put("Transmission",transmission);return out;
    }
    public static Plan prepare(NativeLightBlock.Kind kind,CompoundTag current,CompoundTag values){
        var fields=normalize(current);if(values==null||values.isEmpty())return new Plan(false,fields);if(!NativeCopiedSettingsValidation.valid(values))throw new IllegalArgumentException("Invalid copied Light settings");var inherited=NativeScreenSettings.read(fields,NativeScreenCatalog.INSTANCE);var old=NativeLightSettings.read(fields,inherited.channels(),NativeScreenCatalog.INSTANCE::material).light();
        int trigger=integer(values,"redstone_trigger",old.trigger);if(trigger<0||trigger>2)trigger=old.trigger;
        int face=values.contains("light_face_texture",Tag.TAG_INT)?ModernFinishCatalog.storedChoice(values.getInt("light_face_texture")):old.faceTexture;
        int off=values.contains("light_off_face_texture",Tag.TAG_INT)?values.getInt("light_off_face_texture")<0?-1:ModernFinishCatalog.storedChoice(values.getInt("light_off_face_texture")):old.offFaceTexture;
        boolean selected="light".equals(values.getString("primary_kind"));int texture=selected&&values.contains("primary_texture",Tag.TAG_INT)?ProgrammableLightTextures.clamp(values.getInt("primary_texture")):old.texture;
        if(kind==NativeLightBlock.Kind.FRAME&&values.contains("small_input",Tag.TAG_BYTE))fields.putBoolean("smallInput",values.getBoolean("small_input"));
        boolean tile=inherited.housing().tileSides;int layout=inherited.housing().layout();if(values.contains("slab_tile_sides",Tag.TAG_BYTE)&&tile!=values.getBoolean("slab_tile_sides")){tile=values.getBoolean("slab_tile_sides");layout=tile?1:0;}if(values.contains("texture_layout",Tag.TAG_INT)&&layout!=values.getInt("texture_layout")){layout=values.getInt("texture_layout");tile=layout==1;}fields.putInt("MainTextureLayout",layout);fields.putBoolean("SlabTileSides",tile);
        var signal=values.getCompound("signal_settings");boolean hasSignal=values.contains("signal_settings",Tag.TAG_COMPOUND);var next=new LightData(texture,face,off,Math.max(0,Math.min(15,integer(values,"light_level",old.configuredLevel))),hasSignal?signal.getBoolean("Brightness"):old.signalBrightness,hasSignal?Math.max(-15,Math.min(15,signal.getInt("Offset"))):old.offset,old.joinedLevel,ProgrammableLightPolicy.manualToggleAllowed(trigger)?flag(values,"active",old.manualOn):old.manualOn,flag(values,"join",old.join),trigger,old.joinedPower);new NativeLightSettings(next).write(fields);
        if(values.contains("wall_texture",Tag.TAG_INT)){fields.putInt("housingTexture",ModernFinishCatalog.storedChoice(values.getInt("wall_texture")));fields.putInt("HousingTextureVersion",1);}
        var channels=inherited.channels();if(values.contains("redstone_channel",Tag.TAG_INT_ARRAY))try{channels=ChannelList.of(values.getIntArray("redstone_channel"));}catch(IllegalArgumentException malformed){/* Source preserves current channels. */}else if(values.contains("redstone_channel",Tag.TAG_INT))channels=ChannelList.of(Math.max(0,values.getInt("redstone_channel")));fields.putIntArray("RedstoneChannels",channels.toArray());fields.putInt("RedstoneChannel",channels.first());
        if(values.contains("FrameAppearance",Tag.TAG_COMPOUND))FrameSettings.read(new ModernHousingTags(values.getCompound("FrameAppearance")),NativeScreenCatalog.INSTANCE::validFrame,NativeScreenCatalog.INSTANCE::validFrameSurface,NativeScreenCatalog.INSTANCE::validMaterial).write(new ModernHousingTags(fields));
        if(values.contains("Transmission",Tag.TAG_COMPOUND)){var forge=fields.getCompound("ForgeData").copy();var all=forge.getCompound(TransmissionSettings.SETTINGS).copy();all.put("main",values.getCompound("Transmission").copy());forge.put(TransmissionSettings.SETTINGS,all);fields.put("ForgeData",forge);}
        boolean applicable=selected||values.contains("FrameAppearance",Tag.TAG_COMPOUND)||values.contains("Transmission",Tag.TAG_COMPOUND);for(String key:new String[]{"texture_layout","slab_tile_sides","small_input","light_face_texture","light_off_face_texture","join","redstone_channel","redstone_trigger","wall_texture","light_level","signal_settings","active"})applicable|=values.contains(key);return new Plan(applicable,fields);
    }
    private NativeCopifierLightEdit(){}
}
